//! Bundled cursor themes: images generated by `scripts/gen_cursors.py` into
//! `assets/cursors/<theme>/<kind>.png`, with hotspots and sizes in
//! `assets/cursors/manifest.json`. Kinds a theme has no image for (the
//! geometric ones, and some for the novelty themes) are drawn as vectors in the
//! theme's colours.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

use super::Image;
use super::art::{self, Palette};
use crate::engine::geom::{Vec2, v2};
use crate::project::model::CursorSkin;

macro_rules! assets {
    ($($theme:literal: [$($kind:literal),*]),* $(,)?) => {
        &[$($(($theme, $kind, include_bytes!(concat!("../../assets/cursors/", $theme, "/", $kind, ".png")))),*),*]
    };
}

/// (theme, kind, PNG bytes).
static ASSETS: &[(&str, &str, &[u8])] = assets! {
    "macos": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
    "windows": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
    "flat": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
    "playful": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
    "pixel": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
    "guns": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
    "items": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
    "animals": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
    "chibi": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
    "cute": ["arrow", "pointing-hand", "open-hand", "closed-hand"],
};

static MANIFEST: &str = include_str!("../../assets/cursors/manifest.json");

#[derive(Deserialize)]
struct Entry {
    hotspot: [f64; 2],
    /// Height relative to the standard arrow.
    scale: f64,
}

fn manifest() -> &'static HashMap<String, HashMap<String, Entry>> {
    static M: OnceLock<HashMap<String, HashMap<String, Entry>>> = OnceLock::new();
    M.get_or_init(|| serde_json::from_str(MANIFEST).expect("assets/cursors/manifest.json is valid"))
}

/// Colours for the kinds a theme draws as vectors.
fn palette(theme: &str) -> Palette {
    let rgb = |r: u8, g: u8, b: u8| [r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0];
    match theme {
        "windows" => Palette { fill: [1.0; 3], ring: [0.0; 3] },
        "flat" => Palette { fill: rgb(74, 99, 128), ring: [1.0; 3] },
        "playful" => Palette { fill: rgb(123, 44, 240), ring: rgb(255, 210, 63) },
        "pixel" => Palette { fill: rgb(255, 194, 26), ring: [0.0; 3] },
        _ => Palette::DEFAULT,
    }
}

/// The image, normalised hotspot and relative height of cursor `kind` in `skin`'s
/// theme. None when `skin` is not a bundled theme.
pub fn cursor(skin: CursorSkin, kind: Option<&str>) -> Option<(Image, Vec2, f64)> {
    let theme = skin.theme()?;
    let kind = kind.unwrap_or("arrow");
    let bundled = ASSETS.iter().find(|a| a.0 == theme && a.1 == kind).and_then(|a| {
        let entry = manifest().get(theme)?.get(kind)?;
        let img = image::load_from_memory(a.2).ok()?.to_rgba8();
        let img = Image { width: img.width(), height: img.height(), rgba: img.into_raw() }.premultiply();
        Some((img, v2(entry.hotspot[0], entry.hotspot[1]), entry.scale))
    });
    Some(bundled.unwrap_or_else(|| art::vector_cursor_in(Some(kind), palette(theme))))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_bundled_image_has_a_manifest_entry() {
        for (theme, kind, png) in ASSETS {
            assert!(manifest().get(*theme).and_then(|t| t.get(*kind)).is_some(), "{theme}/{kind} missing from manifest");
            assert!(image::load_from_memory(png).is_ok(), "{theme}/{kind} is not a valid PNG");
        }
    }

    #[test]
    fn every_theme_draws_every_kind() {
        let kinds = ["arrow", "pointing-hand", "ibeam", "open-hand", "closed-hand", "crosshair", "resize-left-right", "resize-up-down"];
        for skin in CursorSkin::THEMES {
            for kind in kinds {
                let (img, hot, scale) = cursor(skin, Some(kind)).expect("theme");
                assert!(img.width > 0 && img.height > 0 && scale > 0.0);
                assert!((0.0..=1.0).contains(&hot.x) && (0.0..=1.0).contains(&hot.y), "{skin:?}/{kind} hotspot {hot:?}");
            }
        }
    }
}
